import SwiftUI

/// Global semantic color aliases backed by `Assets.xcassets` (`Any Appearance` only).
///
/// Base palette tokens (`alcoveInk`, `alcoveBackground`, `alcovePrimaryFill`, etc.)
/// are auto-generated by Xcode Asset Symbol Extensions from `Alcove/Assets.xcassets`.
/// These aliases map component-level design roles to those shared base swatches.
extension Color {
    // MARK: - Text & Borders
    static var alcoveText: Color { .alcoveInk }
    static var alcoveBorder: Color { .alcoveInk }

    // MARK: - Secondary Button
    static var alcoveSecondaryFill: Color { .alcoveBackground }
    static var alcoveSecondaryMid: Color { .alcovePattern }

    // MARK: - Suggestion Chip
    static var alcoveChipHighlight: Color { .alcoveBackground }

    // MARK: - Message Bubble
    static var alcoveBubbleFill: Color { .alcoveBackground }

    // MARK: - Alerts, Menus & Containers
    static var alcoveAlertSurface: Color { .alcoveSurface }
    static var alcoveContainerSurface: Color { .alcoveSurface }

    // MARK: - Progress
    static var alcoveProgressActive: Color { .alcovePrimaryFill }
}

extension ShapeStyle where Self == Color {
    // MARK: - Text & Borders
    static var alcoveText: Color { .alcoveText }
    static var alcoveBorder: Color { .alcoveBorder }

    // MARK: - Secondary Button
    static var alcoveSecondaryFill: Color { .alcoveSecondaryFill }
    static var alcoveSecondaryMid: Color { .alcoveSecondaryMid }

    // MARK: - Suggestion Chip
    static var alcoveChipHighlight: Color { .alcoveChipHighlight }

    // MARK: - Message Bubble
    static var alcoveBubbleFill: Color { .alcoveBubbleFill }

    // MARK: - Alerts, Menus & Containers
    static var alcoveAlertSurface: Color { .alcoveAlertSurface }
    static var alcoveContainerSurface: Color { .alcoveContainerSurface }

    // MARK: - Progress
    static var alcoveProgressActive: Color { .alcoveProgressActive }
}
